      "content": "{\n  \"name\": \"dsh-claude-move\",\n  \"description\": \"Four-source migration wizard: copy Claude Code, Codex, OpenCode and Hermes sessions, memories, skills, instructions and slash commands into DeepSeek Harness as resumable sessions — copy-only, approval-gated, idempotent\",\n  \"version\": \"0.4.19\",\n  \"type\": \"module\",\n  \"main\": \"./index.mjs\",\n  \"exports\": {\n    \".\": \"./index.mjs\",\n    \"./client\": \"./client/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"homepage\": \"https://github.com/PerryLink/dsh-claude-move#readme\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/PerryLink/dsh-claude-move.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/PerryLink/dsh-claude-move/issues\"\n  },\n  \"files\": [\n    \"index.mjs\",\n    \"types.d.ts\",\n    \"lib\",\n    \"client\",\n    \"assets\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.en.md\",\n    \"README.es.md\",\n    \"README.pt.md\",\n    \"README.hi.md\",\n    \"CHANGELOG.md\",\n    \"LICENSE\",\n    \"NOTICE\",\n    \"THIRD_PARTY_NOTICES.md\"\n  ],\n  \"dsh\": {\n    \"manifestVersion\": 1,\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"immediately\": true\n    }\n  },\n  \"dshWorkshop\": {\n    \"schema\": \"omdsh-workshop-package/v1\",\n    \"type\": \"plugin\",\n    \"integration\": {\n      \"protocol\": \"harness-profile\",\n      \"artifact\": \"cordis.patch.yml\"\n    },\n    \"install\": {\n      \"mode\": \"transactional\",\n      \"adapter\": \"profile-bundle\",\n      \"failurePolicy\": \"generation-rollback\",\n      \"touchesCurrentBeforeActivation\": false\n    },\n    \"lifecycle\": {\n      \"activation\": \"hot-reload\",\n      \"dispose\": \"supported\"\n    },\n    \"permissions\": [\n      \"filesystem:read\",\n      \"filesystem:write